@@ -0,0 +1,140 @@
+package com.example.contact;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.options.AriaRole;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.ButtonElement;
+import org.vaadin.addons.dramafinder.element.DialogElement;
+import org.vaadin.addons.dramafinder.element.EmailFieldElement;
+import org.vaadin.addons.dramafinder.element.TextAreaElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/contact";
+    }
+
+    @Test
+    void emptySendShowsTheErrorsAndSendsNothing() {
+        open();
+
+        sendButton().click();
+
+        TextFieldElement.getByLabel(page, "Name").assertErrorMessage("Name is required");
+        EmailFieldElement.getByLabel(page, "Email").assertErrorMessage("Give an e-mail address or a phone number");
+        TextAreaElement.getByLabel(page, "Message").assertErrorMessage("Message is required");
+        assertThat(page.getByText("Message sent")).not().isVisible();
+    }
+
+    @Test
+    void validMessageIsSentListedAndTheFormIsCleared() {
+        open();
+        fill("Jane", "jane@example.com", "", "Hello from the browser");
+
+        sendButton().click();
+
+        assertThat(page.getByText("Message sent")).isVisible();
+        assertThat(page.getByText("Hello from the browser")).isVisible();
+        TextFieldElement.getByLabel(page, "Name").assertValue("");
+        TextAreaElement.getByLabel(page, "Message").assertValue("");
+        sendButton().assertDisabled();
+
+        TextFieldElement.getByLabel(page, "Phone").setValue("555 0100");
+
+        sendButton().assertEnabled();
+    }
+
+    @Test
+    void enterInTheMessageSendsTheMessage() {
+        open();
+        fill("Jane", "", "555 0100", "Sent with Enter");
+
+        TextAreaElement.getByLabel(page, "Message").focus();
+        page.keyboard().press("Enter");
+
+        assertThat(page.getByText("Message sent")).isVisible();
+        assertThat(page.getByText("Sent with Enter")).isVisible();
+    }
+
+    @Test
+    void leavingWithTypedTextAsksFirstAndKeepEditingStaysPut() {
+        open();
+        fill("Jane", "", "", "Half written");
+
+        aboutLink().click();
+
+        DialogElement dialog = DialogElement.getByHeaderText(page, "Discard your message?");
+        dialog.assertOpen();
+        assertThat(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("About"))).not().isVisible();
+
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing")).click();
+
+        dialog.assertClosed();
+        TextAreaElement.getByLabel(page, "Message").assertValue("Half written");
+    }
+
+    @Test
+    void discardGoesOnToTheAboutView() {
+        open();
+        fill("Jane", "", "", "Half written");
+        aboutLink().click();
+
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Discard")).click();
+
+        assertThat(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("About"))).isVisible();
+    }
+
+    @Test
+    void leavingWithAnEmptyFormGoesStraightToTheAboutView() {
+        open();
+
+        aboutLink().click();
+
+        assertThat(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("About"))).isVisible();
+        assertThat(page.getByText("Discard your message?")).not().isVisible();
+    }
+
+    @Test
+    void sentMessagesAreStillListedAfterComingBack() {
+        open();
+        fill("Persisted", "persisted@example.com", "", "Still here");
+        sendButton().click();
+        assertThat(page.getByText("Still here")).isVisible();
+
+        aboutLink().click();
+        assertThat(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("About"))).isVisible();
+        page.goBack();
+
+        assertThat(page.getByText("Still here")).isVisible();
+    }
+
+    private void open() {
+        page.navigate(getUrl());
+    }
+
+    private void fill(String name, String email, String phone, String message) {
+        TextFieldElement.getByLabel(page, "Name").setValue(name);
+        EmailFieldElement.getByLabel(page, "Email").setValue(email);
+        TextFieldElement.getByLabel(page, "Phone").setValue(phone);
+        TextAreaElement.getByLabel(page, "Message").setValue(message);
+    }
+
+    private ButtonElement sendButton() {
+        return ButtonElement.getByText(page, "Send");
+    }
+
+    private com.microsoft.playwright.Locator aboutLink() {
+        return page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About"));
+    }
+}
