+import com.vaadin.flow.component.notification.NotificationTester;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextAreaTester;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.component.textfield.TextFieldTester;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void freshFormIsEmptyAndSendIsEnabled() {
+        navigate(ContactView.class);
+
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void emptyFormMarksEveryFailingFieldAndSendsNothing() {
+        navigate(ContactView.class);
+        int sentBefore = listedMessages().size();
+
+        test(send()).click();
+
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+        assertFalse(phone().isInvalid());
+        assertTrue(message().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+        assertFalse($(Notification.class).exists());
+        assertEquals(sentBefore, listedMessages().size());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void malformedEmailIsRejectedAndTypedValuesStay() {
+        navigate(ContactView.class);
+        fill("Jane", "jane@example", "", "Hello");
+
+        test(send()).click();
+
+        assertTrue(email().isInvalid());
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertFalse(name().isInvalid());
+        assertFalse(message().isInvalid());
+        assertEquals("Jane", name().getValue());
+        assertEquals("jane@example", email().getValue());
+        assertEquals("Hello", message().getValue());
+        assertFalse($(Notification.class).exists());
+    }
+
+    @Test
+    void messageLongerThan500CharactersIsRejected() {
+        navigate(ContactView.class);
+        fill("Jane", "jane@example.com", "", "x".repeat(501));
+
+        test(send()).click();
+
+        assertTrue(message().isInvalid());
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+        assertFalse($(Notification.class).exists());
+    }
+
+    @Test
+    void messageOf500CharactersIsAccepted() {
+        navigate(ContactView.class);
+        fill("Jane", "jane@example.com", "", "x".repeat(500));
+
+        test(send()).click();
+
+        assertFalse(message().isInvalid());
+        assertEquals("Message sent", notificationText());
+    }
+
+    @Test
+    void phoneNumberAloneIsEnough() {
+        navigate(ContactView.class);
+        fill("Jane", "", "+358 40 123 4567", "Call me");
+
+        test(send()).click();
+
+        assertFalse(email().isInvalid());
+        assertEquals("Message sent", notificationText());
+    }
+
+    @Test
+    void emailAloneIsEnough() {
+        navigate(ContactView.class);
+        fill("Jane", "jane@example.com", "", "Write to me");
+
+        test(send()).click();
+
+        assertFalse(email().isInvalid());
+        assertEquals("Message sent", notificationText());
+    }
+
+    @Test
+    void validMessageBecomesFirstRowAndFieldsAreCleared() {
+        navigate(ContactView.class);
+        fill("Jane", "jane@example.com", "", "Hello there");
+
+        test(send()).click();
+
+        ContactMessage first = listedMessages().get(0);
+        assertEquals("Jane", first.name());
+        assertEquals("Hello there", first.message());
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertFalse(send().isEnabled());
+    }
+
+    @Test
+    void sentMessagesAreListedNewestFirst() {
+        navigate(ContactView.class);
+        fill("First", "first@example.com", "", "one");
+        test(send()).click();
+        fill("Second", "second@example.com", "", "two");
+        test(send()).click();
+
+        List<ContactMessage> messages = listedMessages();
+        assertEquals("Second", messages.get(0).name());
+        assertEquals("First", messages.get(1).name());
+    }
+
+    @Test
+    void enterSendsTheMessage() {
+        navigate(ContactView.class);
+        fill("Jane", "", "555 0100", "Call me");
+
+        fireShortcut(Key.ENTER);
+
+        assertEquals("Message sent", notificationText());
+        assertEquals("Jane", listedMessages().get(0).name());
+    }
+
+    @Test
+    void enterDoesNothingWhileSendIsDisabled() {
+        navigate(ContactView.class);
+        fill("Jane", "", "555 0100", "Call me");
+        test(send()).click();
+        int sentAfterSend = listedMessages().size();
+
+        fireShortcut(Key.ENTER);
+
+        assertEquals(sentAfterSend, listedMessages().size());
+        assertFalse(name().isInvalid());
+        assertFalse(message().isInvalid());
+    }
+
+    @Test
+    void sendIsDisabledAfterSendingUntilTheNextEdit() {
+        navigate(ContactView.class);
+        fill("Jane", "", "555 0100", "Call me");
+        test(send()).click();
+        assertFalse(send().isEnabled());
+
+        TextFieldTester<TextField, String> phoneTester = test(phone());
+        phoneTester.setValue("555 0199");
+
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void leavingWithTypedTextAsksFirstAndKeepEditingStaysOnTheView() {
+        navigate(ContactView.class);
+        fill("Jane", "", "", "Half written");
+
+        test(link()).click();
+        Dialog leaveDialog = dialog();
+
+        assertTrue(leaveDialog.isOpened());
+        assertInstanceOf(ContactView.class, getCurrentView());
+
+        test($(Button.class).withText("Keep editing").single()).click();
+
+        assertFalse(leaveDialog.isOpened());
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertEquals("Jane", name().getValue());
+        assertEquals("Half written", message().getValue());
+    }
+
+    @Test
+    void discardGoesOnToTheAboutView() {
+        navigate(ContactView.class);
+        fill("Jane", "", "", "Half written");
+        test(link()).click();
+
+        test($(Button.class).withText("Discard").single()).click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+    }
+
+    @Test
+    void enterBelongsToTheLeaveDialogWhileItIsOpen() {
+        navigate(ContactView.class);
+        fill("Jane", "jane@example.com", "", "Half written");
+        test(link()).click();
+        int sentBefore = listedMessages().size();
+
+        fireShortcut(Key.ENTER);
+
+        assertEquals(sentBefore, listedMessages().size());
+        assertFalse($(Notification.class).exists());
+
+        test($(Button.class).withText("Keep editing").single()).click();
+        fireShortcut(Key.ENTER);
+
+        assertEquals(sentBefore + 1, listedMessages().size());
+        assertEquals("Message sent", notificationText());
+    }
+
+    @Test
+    void navigatingAwayFromAnyOtherPlaceAlsoAsksFirst() {
+        navigate(ContactView.class);
+        fill("Jane", "", "", "Half written");
+
+        UI.getCurrent().navigate(AboutView.class);
+
+        assertTrue(dialog().isOpened());
+        assertInstanceOf(ContactView.class, getCurrentView());
+    }
+
+    @Test
+    void leavingWithAnEmptyFormDoesNotAsk() {
+        navigate(ContactView.class);
+
+        test(link()).click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertFalse($(Dialog.class).exists());
+    }
+
+    @Test
+    void sentMessagesAreStillListedWhenComingBack() {
+        navigate(ContactView.class);
+        fill("Persisted", "persisted@example.com", "", "Still here");
+        test(send()).click();
+
+        test(link()).click();
+        assertInstanceOf(AboutView.class, getCurrentView());
+        navigate(ContactView.class);
+
+        assertEquals("Persisted", listedMessages().get(0).name());
+    }
+
+    private void fill(String nameValue, String emailValue, String phoneValue, String messageValue) {
+        TextFieldTester<TextField, String> nameTester = test(name());
+        nameTester.setValue(nameValue);
+        TextFieldTester<EmailField, String> emailTester = test(email());
+        emailTester.setValue(emailValue);
+        TextFieldTester<TextField, String> phoneTester = test(phone());
+        phoneTester.setValue(phoneValue);
+        TextAreaTester<TextArea> messageTester = test(message());
+        messageTester.setValue(messageValue);
+    }
+
+    private String notificationText() {
+        NotificationTester<Notification> notification = test($(Notification.class).single());
+        return notification.getText();
+    }
+
+    @SuppressWarnings("unchecked")
+    private List<ContactMessage> listedMessages() {
+        Grid<ContactMessage> grid = $(Grid.class).single();
+        return grid.getListDataView().getItems().toList();
+    }
+
+    private TextField name() {
+        return $(TextField.class).withLabel("Name").single();
+    }
+
+    private EmailField email() {
+        return $(EmailField.class).single();
+    }
+
+    private TextField phone() {
+        return $(TextField.class).withLabel("Phone").single();
+    }
+
+    private TextArea message() {
+        return $(TextArea.class).single();
+    }
+
+    private Button send() {
+        return $(Button.class).withText("Send").single();
+    }
+
+    private RouterLink link() {
+        return $(RouterLink.class).withText("About").single();
+    }
+
+    private Dialog dialog() {
+        return $(Dialog.class).single();
+    }
+}
